files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #6f7073;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #000000;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #fdbb2d;
  --vt-line: #d6d0c9;

  min-height: 100vh;
  margin: 0;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Fira Sans', 'Open Sans', sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 3px solid var(--vt-accent);
  outline-offset: 2px;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 280px;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 40px;
  padding: 40px 24px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.logo {
  display: inline-block;
}

.brand {
  font-family: 'Syne', sans-serif;
  font-size: 1.75rem;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--vt-on-accent);
}

.navLinks {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}

.navLinks a {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--vt-on-accent);
  font-family: 'Syne', sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: color 0.2s ease, background 0.2s ease;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-on-accent);
  background: var(--vt-accent-on-deep);
}

.main {
  margin-left: 280px;
}

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 80px 60px;
  overflow: hidden;
  border-bottom: 10px solid var(--vt-accent);
}

.heroBg {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-size: cover;
  background-position: center;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(90deg, var(--vt-surface-deep) 0%, var(--vt-accent) 130%);
  opacity: 0.72;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 640px;
  color: var(--vt-on-deep);
}

.heroKicker {
  margin: 0 0 12px;
  color: var(--vt-on-deep);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  opacity: 0.9;
}

.heroTitle {
  margin: 0 0 16px;
  font-family: 'Syne', sans-serif;
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 800;
  line-height: 0.95;
  color: var(--vt-on-deep);
}

.heroText {
  margin: 0 0 28px;
  max-width: 440px;
  color: var(--vt-on-deep);
  font-size: 1.05rem;
  line-height: 1.6;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.buttonGhost,
.buttonSolid {
  display: inline-block;
  padding: 12px 28px;
  border-radius: 999px;
  font-family: 'Syne', sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.buttonGhost {
  border: 2px solid var(--vt-on-deep);
  background: transparent;
  color: var(--vt-on-deep);
}

.buttonGhost:hover,
.buttonGhost:focus-visible {
  background: var(--vt-on-deep);
  border-color: var(--vt-on-deep);
  color: var(--vt-accent-ink);
}

.buttonSolid {
  border: 2px solid var(--vt-accent-ink);
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

.buttonSolid:hover,
.buttonSolid:focus-visible {
  background: var(--vt-accent);
  border-color: var(--vt-accent);
  color: var(--vt-on-accent);
}

.section,
.sectionAlt {
  padding: 100px 60px;
}

.sectionAlt {
  background: var(--vt-surface-2);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
}

.eyebrow {
  margin: 0 0 10px;
  color: var(--vt-accent-ink);
  font-family: 'Syne', sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.title {
  margin: 0 0 24px;
  font-family: 'Syne', sans-serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  line-height: 1.05;
  color: var(--vt-ink);
}

.storyGrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 60px;
  align-items: center;
}

.storyGrid:has(.storyMedia) {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.storyMedia {
  position: relative;
  min-width: 0;
}

.storyImage {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  border: 8px solid var(--vt-accent);
  border-radius: 20px;
  transform: rotate(-2deg);
}

.storyText p {
  margin: 0 0 16px;
  color: var(--vt-ink-soft);
  font-size: 1rem;
  line-height: 1.7;
}

.storyText p:last-child {
  margin-bottom: 0;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 30px;
  margin-top: 40px;
}

.card {
  display: flex;
  min-width: 0;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--vt-line);
  border-radius: 20px;
  background: var(--vt-surface);
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  border-color: var(--vt-accent);
}

.cardMedia {
  position: relative;
  min-width: 0;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--vt-surface-2);
}

.cardImage {
  display: block;
  width: 100%;
  height: 100%;
  max-width: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.card:hover .cardImage {
  transform: scale(1.03);
}

.pill {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 6px 14px;
  border-radius: 999px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-family: 'Syne', sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
}

.duration {
  position: absolute;
  bottom: 16px;
  left: 16px;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  font-size: 0.7rem;
  font-weight: 600;
}

.cardBody {
  padding: 24px;
}

.cardTitle {
  margin: 0 0 8px;
  font-family: 'Syne', sans-serif;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--vt-ink);
}

.cardDesc {
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 0.95rem;
  line-height: 1.6;
}

.priceGrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 60px;
  align-items: center;
}

.priceGrid:has(.priceMedia) {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.priceListBlock {
  max-width: 560px;
  min-width: 0;
}

.priceList {
  margin-top: 30px;
}

.priceRow {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 18px 0;
  border-bottom: 1px solid var(--vt-line);
}

.priceRow:last-child {
  border-bottom: none;
}

.priceName {
  flex-shrink: 0;
  font-family: 'Syne', sans-serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--vt-ink);
}

.divider {
  flex: 1;
  height: 2px;
  background: var(--vt-line);
  transform: translateY(-4px);
}

.priceValue {
  flex-shrink: 0;
  font-family: 'Syne', sans-serif;
  font-size: 1rem;
  font-weight: 700;
  color: var(--vt-accent-ink);
}

.priceMedia {
  position: relative;
  min-width: 0;
}

.priceImage {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  border: 8px solid var(--vt-accent);
  border-radius: 20px;
  transform: rotate(3deg);
}

.contact {
  background: var(--vt-surface-2);
}

.contactHeader {
  background: var(--vt-surface-deep);
  text-align: center;
}

.contactHeader .container {
  padding: 80px 60px;
}

.titleLight {
  margin: 0;
  font-family: 'Syne', sans-serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--vt-on-deep);
}

.contact > .container {
  padding: 80px 60px;
}

.contactGrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 60px;
  align-items: center;
  margin-bottom: 60px;
}

.contactInfo {
  max-width: 480px;
  min-width: 0;
}

.contactHeading {
  margin: 0 0 16px;
  font-family: 'Syne', sans-serif;
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--vt-ink);
}

.contactLine {
  margin: 0 0 8px;
}

.contactLine a {
  color: var(--vt-accent-ink);
  font-weight: 600;
}

.contactLine a:hover,
.contactLine a:focus-visible {
  color: var(--vt-accent);
}

.social {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}

.areas {
  margin: 20px 0 0;
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
  line-height: 1.5;
}

.hoursCard {
  max-width: 360px;
  min-width: 0;
  padding: 20px;
  background: var(--vt-accent-ink);
  border-radius: 20px;
  transform: rotate(3deg);
}

.hoursInner {
  min-width: 0;
  max-width: 100%;
  padding: 28px 32px;
  background: var(--vt-accent);
  border-radius: 20px;
  transform: rotate(-3deg);
  color: var(--vt-on-accent);
  text-align: center;
}

.hoursTitle {
  margin: 0 0 8px;
  font-family: 'Syne', sans-serif;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--vt-on-accent);
}

.hoursText {
  margin: 0;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--vt-on-accent);
}

.footer {
  padding: 60px;
  background: var(--vt-surface-deep);
  border-top: 10px solid var(--vt-accent);
  color: var(--vt-on-deep);
}

.footer .container {
  max-width: 1200px;
  margin: 0 auto;
}

.footerTop {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 20px;
  font-family: 'Syne', sans-serif;
  font-size: 0.9rem;
  font-weight: 700;
}

.footerTop span {
  color: var(--vt-on-deep);
}

.footerPostcode {
  margin: 12px 0 0;
  color: var(--vt-on-deep);
  font-size: 0.85rem;
  opacity: 0.75;
}

.contact > .container > :last-child,
.contact > .container > :last-child :where(a, span, p, h1, h2, h3, h4, h5, h6, strong) {
  color: var(--vt-on-deep);
}

.storyBody,
.priceListBlock {
  min-width: 0;
}

@media (max-width: 991px) {
  .sidebar {
    position: static;
    width: 100%;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
    padding: 16px 24px;
  }

  .logo {
    margin-bottom: 0;
  }

  .navLinks {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 8px;
  }

  .main {
    margin-left: 0;
  }

  .hero {
    min-height: 70vh;
    padding: 60px 24px;
  }

  .section,
  .sectionAlt {
    padding: 60px 24px;
  }

  .storyGrid,
  .storyGrid:has(.storyMedia),
  .priceGrid,
  .priceGrid:has(.priceMedia),
  .contactGrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .servicesGrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .contactHeader .container,
  .contact > .container {
    padding: 60px 24px;
  }

  .footer {
    padding: 40px 24px;
  }
}

@media (max-width: 600px) {
  .sidebar {
    flex-direction: column;
    text-align: center;
  }

  .navLinks {
    justify-content: center;
  }

  .hero {
    padding: 40px 20px;
  }

  .heroTitle {
    font-size: 2.6rem;
  }

  .heroActions {
    flex-direction: column;
    align-items: stretch;
  }

  .buttonGhost,
  .buttonSolid {
    width: 100%;
    text-align: center;
  }

  .footerTop {
    flex-direction: column;
    align-items: center;
  }
}
